<?php
// Batch workflows reuse the existing import/return/borrow ledgers. No stock is
// written while preparing a review, and a whole batch commits in one transaction.
function workflow_types(){return ['Manual Outflow','Borrow Issue','Non-Sellable Release','Platform Transfer'];}
function workflow_access($kind){$action=['Manual Outflow'=>'manual_outflow','Borrow Issue'=>'borrow_issue','Non-Sellable Release'=>'nonsellable_out','Platform Transfer'=>'transfer_platform'][$kind]??'';if(!$action||!can_action($action))throw new Exception('Your account cannot perform this transaction.');}
function workflow_batch($id,$lock=false){$q=db()->prepare('SELECT * FROM import_batches WHERE id=?'.($lock?' FOR UPDATE':''));$q->execute([(int)$id]);$b=$q->fetch();if(!$b||!in_array($b['import_type'],workflow_types(),true))throw new Exception('Batch not found.');$b['workflow']=(json_decode($b['result_json']??'[]',true)['workflow']??[]);if(($b['workflow']['version']??'')!=='5.5.0')throw new Exception('Unsupported batch.');return $b;}
function workflow_owner($b){workflow_access($b['import_type']);if(current_user()['role']!=='Admin'&&(int)$b['user_id']!==current_user()['id'])throw new Exception('Only the preparer or Admin can change this batch.');}
function workflow_text($value,$label,$max=150){$value=trim((string)$value);if($value===''||mb_strlen($value)>$max)throw new Exception($label.' is required (up to '.$max.' characters).');return $value;}
function workflow_input($kind,$input){
 workflow_access($kind);$data=['txn_date'=>process_date($input['txn_date']??''),'ref'=>workflow_text($input['reference_no']??$input['borrow_ref']??'','Reference',100)];require_open_inventory_date($data['txn_date']);
 if($kind==='Borrow Issue'){if(!preg_match('/^[A-Za-z0-9_-]{6,90}$/D',$data['ref']))throw new Exception('Borrow reference must contain 6 to 90 letters, numbers, hyphens or underscores.');$data['borrower']=workflow_text($input['borrower']??'','Borrower');$data['department']=workflow_text($input['department']??'','Department');$data['reason']=process_reason($input['reason']??'');$due=$input['due_date']??'';$d=DateTime::createFromFormat('!Y-m-d',$due);if(!$d||$d->format('Y-m-d')!==$due||$due<$data['txn_date'])throw new Exception('Due date must be on or after the issue date.');$data['due_date']=$due;}
 elseif($kind==='Platform Transfer'){$data['reason']=process_reason($input['reason']??'');$data['from']=stock_platform($input['from_platform']??'');$data['to']=stock_platform($input['to_platform']??'');if($data['from']===$data['to'])throw new Exception('Source and destination must be different.');}
 else{$data['type']=$input['type']??'';$allowed=$kind==='Non-Sellable Release'?['Disposal','Return to Supplier','Rework','Repackaging']:['Direct Sale','Transfer Out','Internal Use','Marketing','Sponsorship','Freebie','Supplier Return'];if(!in_array($data['type'],$allowed,true))throw new Exception('Select a valid transaction purpose.');$data['reason']=$kind==='Non-Sellable Release'?process_reason($input['reason']??''):'';$data['recipient']=$kind==='Manual Outflow'?workflow_text($input['recipient']??'','Recipient / Business Unit'):'';}
 $items=$input['items']??[];if($kind==='Platform Transfer')$items=[['product_id'=>$input['product_id']??0,'qty'=>$input['qty']??0]];if(!is_array($items)||!count($items)||count($items)>100)throw new Exception('Enter 1 to 100 item lines.');$data['items']=[];$seen=[];
 foreach($items as $item){$source=$kind==='Non-Sellable Release'?whole_number($item['source_id']??'','Original source',1):0;$pid=$source?0:whole_number($item['product_id']??'','Product',1);if($source){$q=db()->prepare('SELECT product_id FROM non_sellable WHERE id=?');$q->execute([$source]);$pid=(int)$q->fetchColumn();if(!$pid)throw new Exception('Original restricted source not found.');}$key=$source?'NS-'.$source:(string)$pid;if(isset($seen[$key]))throw new Exception('Combine duplicate products / source records into one line.');$seen[$key]=true;$data['items'][]=['product_id'=>$pid,'qty'=>whole_number($item['qty']??'','Quantity',1),'source_id'=>$source];}
 return $data;
}
function workflow_plan($kind,$data){
 require_open_inventory_date($data['txn_date']);$plan=[];$restrictedUsed=[];
 foreach($data['items'] as $item){$pid=$item['product_id'];$p=active_product($pid);$s=stock_row($pid);$qty=$item['qty'];$row=$item+['name'=>$p['name'],'sku'=>$p['master_sku'],'signature'=>count_stock_signature($pid),'sellable_before'=>(int)$s['current'],'physical_before'=>(int)$s['physical']];
  if($kind==='Non-Sellable Release'){$q=db()->prepare('SELECT * FROM non_sellable WHERE id=?');$q->execute([$item['source_id']]);$source=$q->fetch();if(!$source||$source['reversed_by_request']!==null||(int)$source['product_id']!==$pid)throw new Exception('Original restricted entry is unavailable.');if($source['txn_date']>$data['txn_date'])throw new Exception('Release date cannot precede its source receipt.');$available=(int)$source['qty']-release_total($source['id']);$restrictedUsed[$pid]=($restrictedUsed[$pid]??0)+$qty;if($qty>$available||$restrictedUsed[$pid]>(int)$s['nonsellable'])throw new Exception('Release exceeds available Non-Sellable stock: '.$p['name']);$row+=['source_ref'=>$source['order_id'],'condition'=>$source['condition_type'],'available'=>$available,'remaining'=>$available-$qty,'restricted_before'=>(int)$s['nonsellable']];}
  else{check_platform_alignment($pid);$before=[];foreach(['Lazada','Shopee','TikTok'] as $platform){$before[$platform]=platform_qty($platform,$pid);if($before[$platform]<0)throw new Exception('Reconcile negative allocations before automatic sourcing: '.$p['name']);}$split=array_fill_keys(array_keys($before),0);
   if($kind==='Platform Transfer'){if($qty>$before[$data['from']])throw new Exception('Transfer exceeds source allocation: '.$p['name']);$split[$data['from']]=$qty;}
   else{if($qty>(int)$s['current']||$qty>array_sum($before))throw new Exception('Insufficient available sellable stock: '.$p['name']);$rank=['Shopee'=>0,'TikTok'=>1,'Lazada'=>2];$ordered=$before;uksort($ordered,fn($a,$b)=>$before[$b]<=>$before[$a]?:$rank[$a]<=>$rank[$b]);$left=$qty;foreach($ordered as $platform=>$available){$split[$platform]=min($available,$left);$left-=$split[$platform];}if($left)throw new Exception('Unable to allocate the requested quantity.');}
   $row+=['before'=>$before,'split'=>$split,'available'=>(int)$s['current'],'remaining'=>(int)$s['current']-($kind==='Platform Transfer'?0:$qty)];
  }$plan[]=$row;
 }return $plan;
}
function workflow_save($id,$w,$status=null){$q=db()->prepare('UPDATE import_batches SET result_json=?,status=COALESCE(?,status) WHERE id=?');$q->execute([json_encode(['workflow'=>$w]),$status,$id]);}
function workflow_event(&$w,$event,$details=''){$w['events'][]=['event'=>$event,'at'=>date(DATE_ATOM),'by'=>current_user(),'details'=>$details];}
function workflow_prepare($kind,$input,$file=null){
 $editing=(int)($input['editing_batch_id']??0);$existing=$editing?workflow_batch($editing):null;if($existing){workflow_owner($existing);if($existing['status']!=='Review'||$existing['import_type']!==$kind)throw new Exception('Only an unsubmitted matching batch can be edited.');if(!hash_equals($existing['workflow']['digest'],(string)($input['editing_digest']??'')))throw new Exception('This draft changed. Reopen it before editing.');}$data=workflow_input($kind,$input);$plan=workflow_plan($kind,$data);$claim=$input['batch_nonce']??'';if(!preg_match('/^[a-f0-9]{32}$/D',$claim))throw new Exception('Refresh the form before preparing this batch.');
 $q=db()->prepare("SELECT id FROM import_batches WHERE import_type=? AND JSON_UNQUOTE(JSON_EXTRACT(result_json,'$.workflow.claim'))=? AND user_id=?");$q->execute([$kind,$claim,current_user()['id']]);if($prior=$q->fetchColumn())throw new Exception('This form was already submitted. Open batch #'.$prior.'.');
 $q=db()->prepare("SELECT id FROM import_batches WHERE import_type=? AND status<>'Cancelled' AND JSON_UNQUOTE(JSON_EXTRACT(result_json,'$.workflow.data.ref'))=? AND id<>?");$q->execute([$kind,$data['ref'],$editing]);if($prior=$q->fetchColumn())throw new Exception('Reference is already in batch #'.$prior.'.');$stored=!empty($file['tmp_name'])?store_upload($file,'batch_documents','BATCH'):null;
 $previous=$existing['workflow']??[];if(!$stored&&$existing)$stored=$existing['stored_path'];$w=['version'=>'5.5.0','kind'=>$kind,'claim'=>$claim,'data'=>$data,'plan'=>$plan,'digest'=>hash('sha256',json_encode($plan)),'attachment_name'=>!empty($file['tmp_name'])?basename($file['name']):($previous['attachment_name']??''),'attachment_hash'=>$stored?hash_file('sha256',__DIR__.'/'.$stored):null,'events'=>$previous['events']??[]];if($existing){$w['previous_plans']=$previous['previous_plans']??[];$w['previous_plans'][]=$previous['plan'];}workflow_event($w,$existing?'Corrected and revalidated':'Prepared for validation');if($existing){workflow_save($editing,$w);db()->prepare('UPDATE import_batches SET filename=?,stored_path=?,rows_read=? WHERE id=?')->execute([$kind.' · '.$data['ref'],$stored,count($plan),$editing]);unset($_SESSION['workflow_edit_'.$kind]);return $editing;}
 db()->prepare('INSERT INTO import_batches(import_type,filename,stored_path,rows_read,units,imported_count,error_count,status,result_json,user_id) VALUES(?,?,?,?,0,0,0,?,?,?)')->execute([$kind,$kind.' · '.$data['ref'],$stored,count($plan),'Review',json_encode(['workflow'=>$w]),current_user()['id']]);$id=(int)db()->lastInsertId();audit('Prepare '.$kind,'Import',(string)$id,$data['ref'].'; no stock changed.');unset($_SESSION['workflow_edit_'.$kind]);return $id;
}
function workflow_change($id,$action,$reason=''){
 return process_transaction(function()use($id,$action,$reason){$b=workflow_batch($id,true);$w=$b['workflow'];workflow_owner($b);if(in_array($b['status'],['Posted','Cancelled'],true))throw new Exception('This batch is already posted or closed.');
  if($action==='refresh'){if($b['status']!=='Review')throw new Exception('Return the request for correction before refreshing.');$w['previous_plans'][]=$w['plan'];$w['plan']=workflow_plan($b['import_type'],$w['data']);$w['digest']=hash('sha256',json_encode($w['plan']));workflow_event($w,'Validation refreshed');workflow_save($id,$w);}
  elseif($action==='submit'){if($b['import_type']!=='Non-Sellable Release'||$b['status']!=='Review')throw new Exception('Only a reviewed restricted release can be submitted.');$fresh=workflow_plan($b['import_type'],$w['data']);if(!hash_equals($w['digest'],hash('sha256',json_encode($fresh))))throw new Exception('Stock changed after validation. Refresh and review the batch.');workflow_event($w,'Submitted for separate Admin approval');workflow_save($id,$w,'Submitted');audit('Physical release awaiting approval','Import',(string)$id,$w['data']['ref']);}
  elseif($action==='return'){if(current_user()['role']!=='Admin'||$b['status']!=='Submitted')throw new Exception('Admin review required.');workflow_event($w,'Returned for correction',process_reason($reason));workflow_save($id,$w,'Review');}
  elseif($action==='cancel'){workflow_event($w,'Cancelled',process_reason($reason));workflow_save($id,$w,'Cancelled');audit('Cancel '.$b['import_type'],'Import',(string)$id,$w['data']['ref']);}
 });
}
function workflow_post($id,$digest,$ack){
 if(!$ack)throw new Exception('Review and acknowledge all quantities before continuing.');
 return process_transaction(function()use($id,$digest){$b=workflow_batch($id,true);$w=$b['workflow'];$kind=$b['import_type'];$data=$w['data'];workflow_access($kind);
  if($kind==='Non-Sellable Release'){if(current_user()['role']!=='Admin'||(int)$b['user_id']===current_user()['id'])throw new Exception('A different Admin must approve this release.');if($b['status']!=='Submitted')throw new Exception('Release must be submitted before approval.');}
  else{workflow_owner($b);if($b['status']!=='Review')throw new Exception('This batch is already posted or closed.');}
  if(!hash_equals($w['digest'],(string)$digest))throw new Exception('Review token changed. Reopen this batch.');$pids=array_unique(array_column($data['items'],'product_id'));sort($pids,SORT_NUMERIC);foreach($pids as $pid){$q=db()->prepare('SELECT id FROM products WHERE id=? FOR UPDATE');$q->execute([$pid]);}
  $plan=workflow_plan($kind,$data);if(!hash_equals($w['digest'],hash('sha256',json_encode($plan))))throw new Exception('Stock changed since validation. Return / refresh the review before posting.');$uid=current_user()['id'];$movements=[];
  if($kind==='Borrow Issue'){$items=[];foreach($plan as $line)foreach($line['split'] as $platform=>$qty)if($qty)$items[]=['product_id'=>$line['product_id'],'source_platform'=>$platform,'qty'=>$qty];$posted=borrow_issue_multiple(['txn_date'=>$data['txn_date'],'due_date'=>$data['due_date'],'borrower'=>$data['borrower'],'borrow_ref'=>$data['ref'],'reason'=>$data['department'].'; '.$data['reason'],'items'=>$items]);$w['borrow_id']=$posted['id'];$w['borrow_ids']=$posted['ids'];foreach($posted['ids'] as $borrowId){$q=db()->prepare('UPDATE outflows o JOIN borrowed_items bi ON bi.outflow_id=o.id SET o.import_batch_id=? WHERE bi.id=?');$q->execute([$id,$borrowId]);}}
  else foreach($plan as $line){$pid=$line['product_id'];$qty=$line['qty'];
   if($kind==='Non-Sellable Release'){$row=db()->prepare('SELECT id FROM non_sellable WHERE id=? FOR UPDATE');$row->execute([$line['source_id']]);db()->prepare('INSERT INTO nonsellable_outflows(txn_date,product_id,qty,type,reference_no,remarks,user_id) VALUES(?,?,?,?,?,?,?)')->execute([$data['txn_date'],$pid,$qty,$data['type'],$data['ref'],$data['reason'].'; Batch #'.$id,$uid]);$release=(int)db()->lastInsertId();db()->prepare('INSERT INTO nonsellable_release_links(release_id,non_sellable_id,qty) VALUES(?,?,?)')->execute([$release,$line['source_id'],$qty]);$movements[]=['source_id'=>$line['source_id'],'release_id'=>$release,'qty'=>$qty];}
   elseif($kind==='Platform Transfer'){$q=db()->prepare('SELECT id FROM platform_transfers WHERE transfer_ref=?');$q->execute([$data['ref']]);if($q->fetchColumn())throw new Exception('This transfer reference is already posted.');db()->prepare('INSERT INTO platform_transfers(transfer_ref,txn_date,product_id,from_platform,to_platform,qty,reason,user_id) VALUES(?,?,?,?,?,?,?,?)')->execute([$data['ref'],$data['txn_date'],$pid,$data['from'],$data['to'],$qty,$data['reason'],$uid]);$movements[]=['transfer_id'=>(int)db()->lastInsertId()];change_platform_stock($data['from'],$pid,-$qty,$data['ref'],$data['txn_date']);change_platform_stock($data['to'],$pid,$qty,$data['ref'],$data['txn_date']);}
   else{$q=db()->prepare('SELECT id FROM outflows WHERE order_id=? AND product_id=? AND type=? AND reversed_by_request IS NULL');$type=$data['type']==='Direct Sale'?'Order':$data['type'];$q->execute([$data['ref'],$pid,$type]);if($q->fetchColumn())throw new Exception('This reference/product was already issued.');foreach($line['split'] as $platform=>$take)if($take){db()->prepare('INSERT INTO outflows(txn_date,platform,order_id,product_id,source_item,qty,type,import_batch_id,dedupe_key,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$data['txn_date'],'Internal',$data['ref'],$pid,'Stock source: '.$platform,$take,$type,$id,hash('sha256','manual|'.$platform.'|'.$data['ref'].'|'.$pid.'|'.$type),$data['recipient'].'; Batch #'.$id,$uid]);$movements[]=['outflow_id'=>(int)db()->lastInsertId(),'platform'=>$platform,'qty'=>$take];change_platform_stock($platform,$pid,-$take,$data['ref'],$data['txn_date']);}}
   check_platform_alignment($pid);
  }
  $w['movements']=$movements;$w['posted_by']=current_user();$w['posted_at']=date(DATE_ATOM);workflow_event($w,$kind==='Non-Sellable Release'?'Approved and physically released':'Confirmed and posted');workflow_save($id,$w,'Posted');db()->prepare('UPDATE import_batches SET units=?,imported_count=? WHERE id=?')->execute([array_sum(array_column($plan,'qty')),count($plan),$id]);audit('Post '.$kind,'Import',(string)$id,$data['ref'].'; '.count($plan).' item lines.');return $id;
 });
}
function receiving_cart_key(){return 'manual_receiving_'.current_user()['id'];}
function receiving_cart(){$c=$_SESSION[receiving_cart_key()]??null;if(!empty($c['editing_id'])){try{if(return_batch($c['editing_id'])['status']!=='Review')$c=null;}catch(Throwable $ex){$c=null;}if(!$c)unset($_SESSION[receiving_cart_key()]);}return $c??['kind'=>'returns','date'=>date('Y-m-d'),'orders'=>[]];}
function receiving_capture($input,$file=null){
 if(!can_action('return_confirm'))throw new Exception('Return receiving access required.');$c=receiving_cart();$kind=$input['transaction_kind']??$c['kind'];if(!in_array($kind,['returns','cancelled'],true))throw new Exception('Select a valid transaction type.');if($kind!==$c['kind']&&$c['orders'])throw new Exception('Clear the existing batch before changing transaction type.');$c['kind']=$kind;$c['date']=process_date($input['txn_date']??$c['date']);
 foreach($c['orders'] as &$order)foreach($order['items'] as &$item){$key=cancelled_order_line_key($order['platform'],$order['order'],$item['product_id']);$v=$input['lines'][$key]??[];$item['selected']=!empty($v['selected']);$item['qty']=$v['qty']??$item['qty'];$item['condition']=$v['condition']??$item['condition'];}unset($item,$order);
 if(!empty($file['tmp_name'])){$c['attachment_path']=store_upload($file,'return_attachments','BATCH');$c['attachment_name']=basename($file['name']);}$_SESSION[receiving_cart_key()]=$c;
}
function receiving_edit($id){
 if(!can_action('return_confirm'))throw new Exception('Return receiving access required.');$b=return_batch($id);if($b['status']!=='Review'||(current_user()['role']!=='Admin'&&(int)$b['created_by']!==current_user()['id']))throw new Exception('Only the preparer or Admin can correct an unposted batch.');$rows=json_decode($b['rows_json'],true);if(empty($rows[0]['manual_lookup']))throw new Exception('Use the original upload correction workflow.');$c=['kind'=>cancelled_order_batch($b)?'cancelled':'returns','date'=>$rows[0]['date'],'orders'=>[],'editing_id'=>$id,'editing_revision'=>(int)$b['revision'],'attachment_path'=>$b['stored_path'],'attachment_name'=>$b['stored_path']?$b['filename']:''];
 foreach($rows as $r){$key=hash('sha256',json_encode([$r['platform'],$r['order']]));if(!isset($c['orders'][$key])){$order=cancelled_order_lookup($r['platform'],$r['order']);foreach($order['items'] as &$item){$item['selected']=false;$item['qty']=max(1,$item['remaining']);$item['condition']='Good Item';}unset($item);$c['orders'][$key]=$order;}$item=&$c['orders'][$key]['items'][$r['product_id']];$item['selected']=true;$item['qty']=$r['qty'];$item['condition']=$r['condition'];unset($item);}$_SESSION[receiving_cart_key()]=$c;
}
function receiving_lookup($input){if(!can_action('return_confirm'))throw new Exception('Return receiving access required.');$c=receiving_cart();$kind=$input['transaction_kind']??'returns';if(!in_array($kind,['returns','cancelled'],true))throw new Exception('Select Return Orders or Cancelled Orders.');if($kind!==$c['kind']&&$c['orders'])throw new Exception('Clear the batch before changing transaction type.');$c['kind']=$kind;$c['date']=process_date($input['txn_date']??$c['date']);
 foreach($c['orders'] as &$order)foreach($order['items'] as &$item){$key=cancelled_order_line_key($order['platform'],$order['order'],$item['product_id']);$v=$input['lines'][$key]??[];$item['selected']=!empty($v['selected']);$item['qty']=$v['qty']??$item['qty'];$item['condition']=$v['condition']??$item['condition'];}unset($item,$order);
 if(!empty($input['remove_order'])){unset($c['orders'][$input['remove_order']]);$_SESSION[receiving_cart_key()]=$c;return;}
 $o=cancelled_order_lookup($input['platform']??'',$input['order_id']??'');$key=hash('sha256',json_encode([$o['platform'],$o['order']]));if(isset($c['orders'][$key]))throw new Exception('This order is already included.');if(count($c['orders'])>=30)throw new Exception('Use up to 30 orders per batch.');foreach($o['items'] as &$i){$i['selected']=false;$i['qty']=max(1,$i['remaining']);$i['condition']='Good Item';}unset($i);$c['orders'][$key]=$o;$_SESSION[receiving_cart_key()]=$c;
}
function receiving_stage($input,$file=null){
 if(!can_action('return_confirm'))throw new Exception('Return receiving access required.');if(empty($input['physical_ack']))throw new Exception('Confirm physical receipt of the selected items.');$c=receiving_cart();if(($input['transaction_kind']??'')!==$c['kind'])throw new Exception('Transaction type changed. Clear and find the orders again.');$date=process_date($input['txn_date']??'');require_open_inventory_date($date);$rows=[];
 foreach($c['orders'] as $order){$fresh=cancelled_order_lookup($order['platform'],$order['order']);foreach($order['items'] as $pid=>$item){$key=cancelled_order_line_key($order['platform'],$order['order'],$pid);$v=$input['lines'][$key]??[];if(empty($v['selected']))continue;$f=$fresh['items'][$pid]??null;if(!$f||!hash_equals($item['signature'],$f['signature']))throw new Exception('The original order changed. Find it again.');if($date<$f['latest_date'])throw new Exception('Receipt date cannot precede the order outflow.');$rows[]=['row'=>count($rows)+1,'date'=>$date,'order'=>$order['order'],'platform'=>$order['platform'],'product_id'=>(int)$pid,'item'=>$f['name'],'qty'=>whole_number($v['qty']??'','Received quantity',1),'condition'=>$v['condition']??'','remarks'=>'Physical receipt confirmed by '.current_user()['name'],'source_signature'=>$f['signature'],'transaction_kind'=>$c['kind']==='cancelled'?'Cancelled Order':'Return Order','manual_lookup'=>true];}}
 if(!$rows||count($rows)>200)throw new Exception('Select 1 to 200 received product lines.');$probe=['batch_ref'=>$c['kind']==='cancelled'?'CAN-VALIDATE':'RET-VALIDATE','revision'=>1,'status'=>'Review','rows_json'=>json_encode($rows)];$a=return_analysis($probe);if($a['errors'])throw new Exception(implode(' · ',$a['errors']));$stored=!empty($file['tmp_name'])?store_upload($file,'return_attachments','BATCH'):null;
 if(!$stored)$stored=$c['attachment_path']??null;$filename=$file['name']??($c['attachment_name']??'Manual Order Lookup');return process_transaction(function()use($rows,$filename,$stored,$c){
  if(!empty($c['editing_id'])){$id=(int)$c['editing_id'];$b=return_batch($id,true);if($b['status']!=='Review'||(int)$b['revision']!==$c['editing_revision']||(current_user()['role']!=='Admin'&&(int)$b['created_by']!==current_user()['id']))throw new Exception('This review changed. Reopen it before correcting.');if(cancelled_order_batch($b)!==($c['kind']==='cancelled'))throw new Exception('Transaction type cannot change on an existing batch.');audit('Correct receiving batch','Return',(string)$id,json_encode(['previous'=>json_decode($b['rows_json'],true),'replacement'=>$rows]));db()->prepare('UPDATE return_batches SET rows_json=?,filename=?,stored_path=?,revision=revision+1 WHERE id=?')->execute([json_encode($rows),$filename,$stored,$id]);}
  else{db()->prepare('INSERT INTO return_batches(batch_ref,filename,stored_path,rows_json,created_by) VALUES(?,?,?,?,?)')->execute([next_ref($c['kind']==='cancelled'?'CAN':'RET').'-'.bin2hex(random_bytes(3)),$filename,$stored,json_encode($rows),current_user()['id']]);$id=(int)db()->lastInsertId();}
  inflow_sync_return_history($id);audit('Review manual receiving','Return',(string)$id,'Order lookup batch; no inventory added.');unset($_SESSION[receiving_cart_key()]);return $id;
 });
}
function workflow_platform_rows($input){$platform=stock_platform($input['platform']??'');$term=trim((string)($input['q']??''));$sql='SELECT p.*,COALESCE(ps.qty,0) pqty,(SELECT alias FROM platform_aliases a WHERE a.platform=? AND a.product_id=p.id ORDER BY id DESC LIMIT 1) alias FROM products p LEFT JOIN platform_stock ps ON ps.product_id=p.id AND ps.platform=? WHERE p.active=1 AND '.inventory_filter_condition('p');$args=[$platform,$platform];if($term!==''){$sql.=' AND (p.name LIKE ? OR p.master_sku LIKE ? OR p.brand LIKE ? OR EXISTS(SELECT 1 FROM platform_aliases ax WHERE ax.platform=? AND ax.product_id=p.id AND (ax.alias LIKE ? OR ax.external_id LIKE ?)))';$like='%'.$term.'%';array_push($args,$like,$like,$like,$platform,$like,$like);}$sql.=' ORDER BY p.brand,p.name';$q=db()->prepare($sql);$q->execute($args);$rows=[];foreach($q as $r){$status=detect_status((int)$r['pqty'],$r['low_stock_threshold']??10);if(!empty($input['status'])&&stock_status_key($status[0])!==$input['status'])continue;$rows[]=[$r['name'],$r['alias']??'',(int)$r['pqty']];}return [$platform,$rows];}
